static RISCVException read_ssp(CPURISCVState *env, int csrno,
                               target_ulong *val)
{
    *val = env->ssp;
    return RISCV_EXCP_NONE;
}

static RISCVException write_ssp(CPURISCVState *env, int csrno,
                                target_ulong val, uintptr_t ra)
{
    env->ssp = val;
    return RISCV_EXCP_NONE;
}

